'use client';
// Isolated response/target harness; mounted into a disposable Web container only.
import {useEffect,useRef,useState} from 'react';import {EditNavigationProvider} from '../components/elements/edit-navigation';import EditSession,{EditDialog} from '../components/elements/edit-session';import FormField from '../components/elements/form-field';import FormDemo from '../examples/form-demo';import type {SaveResult} from '../../../../shared/editor.mjs';
type Values={name:string};
export default function Page(){
 const [open,setOpen]=useState(false),[inline,setInline]=useState(false),[target,setTarget]=useState('A'),[calls,setCalls]=useState<string[]>([]),[commits,setCommits]=useState<Values[]>([]),pending=useRef(new Map<string,(result:SaveResult<Values>)=>void>());
 useEffect(()=>{const control=(event:Event)=>{const detail=(event as CustomEvent).detail;if(detail.kind==='unmount')setOpen(false);if(detail.kind==='target')setTarget(detail.id);if(detail.kind==='resolve')pending.current.get(detail.id)?.(detail.result);};window.addEventListener('fixture:editing',control);return()=>window.removeEventListener('fixture:editing',control);},[]);
 return <EditNavigationProvider><main><h1>Isolated editing lifecycle</h1><FormDemo/><button onClick={()=>setInline(true)}>Open inline</button>{inline&&<EditSession title="Inline fixture" targetKey="inline" options={{initial:{name:"Alpha"},normalize:v=>({...v}),validate:()=>({}),failureMessage:"Failed"}} fields={({editor,state})=><FormField label="Inline name">{attributes=><input {...attributes} name="fixtureInlineName" value={state.values.name} onChange={event=>editor.change("name",event.target.value)}/>}</FormField>} save={async values=>({kind:"saved",values:{...values}})} onCommit={()=>setInline(false)} onClose={()=>setInline(false)}/>}<button onClick={()=>setOpen(true)}>Open fixture</button><output aria-label="fixture calls">{JSON.stringify(calls)}</output><output aria-label="fixture commits">{JSON.stringify(commits)}</output><output aria-label="fixture target">{target}</output>
 {open&&<EditDialog title="Fixture editor" targetKey={target} options={{initial:{name:'Alpha'},normalize:v=>({name:v.name.trim()}),validate:v=>v.name?{}:{name:'Required'},failureMessage:'Failed',timeoutMs:10000}} fields={({editor,state})=><FormField label="Fixture name" error={state.errors.name}>{attributes=><input {...attributes} name="fixtureEditName" value={state.values.name} onChange={event=>editor.change('name',event.target.value)} onBlur={()=>editor.blur('name')}/>}</FormField>} save={(values,signal,{attemptId})=>new Promise(resolve=>{setCalls(previous=>[...previous,attemptId]);pending.current.set(attemptId,resolve);})} onCommit={values=>setCommits(previous=>[...previous,values])} onClose={()=>setOpen(false)}/>}</main></EditNavigationProvider>;
}
